<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\QuestionLearning;
use App\Domain\QuestionLearning\Entity\QuestionExplanationExecution;use App\Domain\QuestionLearning\Enum\ExplanationSafetyMode;use App\Domain\QuestionLearning\Enum\ExplanationStatus;use App\Domain\QuestionLearning\Repository\QuestionExplanationExecutionRepositoryInterface;use App\Domain\QuestionLearning\ValueObject\QuestionExplanationJob;use App\Infrastructure\Persistence\Doctrine\QuestionLearning\Entity\QuestionExplanationExecutionRecord;use Doctrine\DBAL\LockMode;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineQuestionExplanationExecutionRepository implements QuestionExplanationExecutionRepositoryInterface { public function __construct(private readonly EntityManagerInterface $em) {} public function findById(string $id):?QuestionExplanationExecution{$record=$this->em->find(QuestionExplanationExecutionRecord::class,$id);return $record instanceof QuestionExplanationExecutionRecord?$this->map($record):null;}public function findByRequest(string $userId,string $questionId,?string $attemptId,string $algorithmVersion):?QuestionExplanationExecution { $record=$this->em->getRepository(QuestionExplanationExecutionRecord::class)->findOneBy(['userId'=>$userId,'questionId'=>$questionId,'attemptId'=>$attemptId,'algorithmVersion'=>$algorithmVersion]);return $record instanceof QuestionExplanationExecutionRecord?$this->map($record):null;}public function findLatestForUserQuestion(string $userId,string $questionId):?QuestionExplanationExecution{$record=$this->em->createQueryBuilder()->select('e')->from(QuestionExplanationExecutionRecord::class,'e')->where('e.userId=:user')->andWhere('e.questionId=:question')->setParameter('user',$userId)->setParameter('question',$questionId)->orderBy('e.requestedAt','DESC')->setMaxResults(1)->getQuery()->getOneOrNullResult();return $record instanceof QuestionExplanationExecutionRecord?$this->map($record):null;}public function claimNextPending(\DateTimeImmutable $now):?QuestionExplanationJob{return $this->em->wrapInTransaction(function()use($now){$record=$this->em->createQueryBuilder()->select('e')->from(QuestionExplanationExecutionRecord::class,'e')->where('e.status IN (:statuses)')->andWhere('e.retryCount<3')->setParameter('statuses',[ExplanationStatus::PENDING->value,ExplanationStatus::FAILED->value])->orderBy('e.requestedAt','ASC')->setMaxResults(1)->getQuery()->setLockMode(LockMode::PESSIMISTIC_WRITE)->getOneOrNullResult();if(!$record instanceof QuestionExplanationExecutionRecord)return null;$record->status=ExplanationStatus::PROCESSING->value;$record->startedAt=$now;$record->completedAt=null;return new QuestionExplanationJob($record->id,$record->userId,$record->questionId,$record->attemptId,$record->algorithmVersion,$record->safetyMode);});}public function save(QuestionExplanationExecution $e):void{$r=$this->em->find(QuestionExplanationExecutionRecord::class,$e->id)??new QuestionExplanationExecutionRecord();foreach(['id','userId','questionId','attemptId','algorithmVersion','requestedAt'] as $p)$r->$p=$e->$p;$r->safetyMode=$e->safetyMode->value;$r->status=$e->status()->value;$r->retryCount=$e->retryCount();$r->provider=$e->provider();$r->model=$e->model();$r->tokenCount=$e->tokenCount();$r->durationMilliseconds=$e->durationMilliseconds();$r->result=$e->result();$r->errorCode=$e->errorCode();$r->errorMessage=$e->errorMessage();$r->startedAt=$e->startedAt();$r->completedAt=$e->completedAt();$this->em->persist($r);$this->em->flush();}private function map(QuestionExplanationExecutionRecord $r):QuestionExplanationExecution{return new QuestionExplanationExecution($r->id,$r->userId,$r->questionId,$r->attemptId,$r->algorithmVersion,ExplanationSafetyMode::from($r->safetyMode),ExplanationStatus::from($r->status),$r->retryCount,$r->provider,$r->model,$r->tokenCount,$r->durationMilliseconds,$r->result,$r->errorCode,$r->errorMessage,$r->requestedAt,$r->startedAt,$r->completedAt);}}
